<?php
class AdminController extends BaseController { public function index(mysqli $db): void { require_role('admin');$message='';if($_SERVER['REQUEST_METHOD']==='POST'){$a=$_POST['action']??'';if($a==='product_add'){$message=Product::add($db,(int)$_POST['seller_id'],(int)$_POST['category_id'],trim($_POST['name']), (float)$_POST['price'],max(0,(int)$_POST['stock']),trim($_POST['description']))?'Product added.':'Could not add product.';}elseif($a==='product_delete'){Product::delete($db,(int)$_POST['id']);$message='Product deleted.';}elseif($a==='order_status'){Order::updateStatus($db,(int)$_POST['id'],$_POST['status']);$message='Order status updated.';}elseif($a==='seller_status'){Seller::updateStatus($db,(int)$_POST['id'],$_POST['status']);$message='Seller status updated.';}elseif($a==='user_delete'){User::delete($db,(int)$_POST['id']);$message='User removed.';}elseif($a==='category_add'){Category::add($db,trim($_POST['category_name']));$message='Category saved.';}}$d=$this->data($db);$d['message']=$message;$d['products']=Product::all($db);$d['sellers']=Seller::all($db);$d['users']=User::all($db);$d['orders']=Order::all($db);$d['categories']=Category::all($db);$d['categoryOptions']=Category::all($db);$d['sellerOptions']=Seller::approved($db);$d['report']=Order::report($db);render('admin/dashboard',$d);}}
